#!/usr/bin/env node
/**
 * Repo-level hygiene checks.
 *
 * These exist because the real gate — lint, type-check, build, test:all —
 * CANNOT run on a hosted GitHub runner: `@glaze/core` resolves to the Glaze.app
 * SDK install outside the repo, so every one of those commands fails there for
 * reasons that have nothing to do with the change under review. Rather than
 * ship a permanently-red workflow, CI runs the subset that needs no SDK.
 *
 * Everything here is checked against `git ls-files` — the TRACKED set — not the
 * working tree. An ignored file on disk is fine; the same file committed is not.
 *
 * Run locally with: npm run check:repo-hygiene
 */

import { execFileSync } from "node:child_process";
import { readFileSync, existsSync } from "node:fs";
import process from "node:process";
import console from "node:console";

const failures = [];

function fail(check, detail) {
  failures.push({ check, detail });
}

/** Tracked files, as git sees them. */
function trackedFiles() {
  return execFileSync("git", ["ls-files", "-z"], { encoding: "utf8" })
    .split("\0")
    .filter(Boolean);
}

const files = trackedFiles();

// ── 1. No generated or scratch output committed ──────────────────────────────
// Each of these is rewritten by a build, a test run, or the Glaze agent tooling.
// Committing them produces conflicts on every branch and, for coverage output
// and DOM snapshots, leaks absolute paths from the machine that generated them.
const FORBIDDEN_PATHS = [
  { prefix: "node_modules/", why: "dependencies are installed, not committed" },
  { prefix: "coverage/", why: "regenerated by `npm run test:coverage`" },
  { prefix: "test-results/", why: "regenerated by Playwright on every run" },
  { prefix: "playwright-report/", why: "regenerated by Playwright on every run" },
  { prefix: ".glaze-tool-output/", why: "Glaze agent scratch output" },
  { prefix: ".glaze_memory/", why: "superseded by docs/ARCHITECTURE.md and docs/DECISIONS.md" },
  { prefix: ".claude/worktrees/", why: "per-machine agent worktrees" },
  { prefix: ".claude/.cc-writes/", why: "per-machine agent state" },
];

const FORBIDDEN_EXACT = [
  { path: ".icon-hash", why: "cache key for generated icons" },
  { path: ".claude/settings.local.json", why: "per-machine local settings" },
];

for (const file of files) {
  for (const { prefix, why } of FORBIDDEN_PATHS) {
    if (file.startsWith(prefix)) fail("generated-files", `${file} — ${why}`);
  }
  for (const { path, why } of FORBIDDEN_EXACT) {
    if (file === path) fail("generated-files", `${file} — ${why}`);
  }
  if (file.endsWith(".DS_Store")) fail("generated-files", `${file} — macOS junk`);
  if (/^app-icon\./.test(file)) fail("generated-files", `${file} — generated binary asset`);
}

// ── 2. No machine-specific absolute paths ────────────────────────────────────
// The SDK is reached through RELATIVE paths (`../../../sdk/current/...`) on
// purpose, so the checkout stays portable across machines and user accounts. A
// hardcoded /Users/<someone> silently ties the repo to one laptop.
//
// Markdown is exempt FROM THIS RULE ONLY (it is still scanned for secrets in
// check 3): the README, CLAUDE.md and docs/ legitimately quote the Glaze-managed
// install path when explaining where the checkout must live, and docs/DECISIONS.md
// quotes log paths from the sessions it records.
//
// Tests are exempt too, and deliberately so. Synthetic home-directory paths are
// the SUBJECT of assertions there — flake-analysis.check.ts asserts on two of
// them to prove that error signatures normalise paths and line numbers away.
// Flagging those trains people to ignore this check,
// which is worse than the leak it would catch: what actually needs guarding is
// config and generated output, where a real home directory gets baked in and
// silently ties the repo to one machine.
const TEXT_LIKE = /\.(ts|tsx|mjs|cjs|js|jsx|json|html|css|yml|yaml|md)$/;
const IS_MARKDOWN = /\.md$/;
const IS_TEST = /(\.test\.|\.check\.|\.dom\.test\.|__tests__\/|\/fixtures?\/)/;
const ABSOLUTE_PATH = /\/Users\/[A-Za-z0-9._-]+\//;

for (const file of files) {
  if (!TEXT_LIKE.test(file) || IS_MARKDOWN.test(file) || IS_TEST.test(file)) continue;
  if (!existsSync(file)) continue;
  const lines = readFileSync(file, "utf8").split("\n");
  lines.forEach((line, i) => {
    if (ABSOLUTE_PATH.test(line)) {
      fail("absolute-paths", `${file}:${i + 1} — hardcoded home directory`);
    }
  });
}

// ── 3. No obvious secret material ────────────────────────────────────────────
// The Anthropic key is stored in the app's userData directory and never in the
// repo. This is a tripwire in case that ever changes, not a real secret scanner
// — GitHub push protection is the backstop.
//
// Markdown IS scanned here, unlike check 2. Docs are where a key gets pasted
// into an example and forgotten.
const SECRET_PATTERNS = [
  { name: "an Anthropic API key", re: /sk-ant-api[0-9]{2}-[A-Za-z0-9_-]{20,}/ },
  { name: "a GitHub token", re: /\b(ghp|gho|ghs|ghr)_[A-Za-z0-9]{30,}\b/ },
  { name: "a GitHub fine-grained token", re: /\bgithub_pat_[A-Za-z0-9_]{50,}\b/ },
  { name: "an AWS access key", re: /\bAKIA[0-9A-Z]{16}\b/ },
  { name: "a private key block", re: /-----BEGIN [A-Z ]*PRIVATE KEY-----/ },
];

for (const file of files) {
  if (!TEXT_LIKE.test(file) || !existsSync(file)) continue;
  const lines = readFileSync(file, "utf8").split("\n");
  lines.forEach((line, i) => {
    for (const { name, re } of SECRET_PATTERNS) {
      if (re.test(line)) fail("secrets", `${file}:${i + 1} — looks like ${name}`);
    }
  });
}

// ── 4. Lockfile tracked and in sync with the manifest ────────────────────────
// A missing or stale lockfile means two developers resolve different trees from
// the same commit, which shows up later as a bug nobody can reproduce.
if (!files.includes("package-lock.json")) {
  fail("lockfile", "package-lock.json is not tracked");
} else {
  const pkg = JSON.parse(readFileSync("package.json", "utf8"));
  const lock = JSON.parse(readFileSync("package-lock.json", "utf8"));
  const root = lock.packages?.[""] ?? {};

  for (const field of ["dependencies", "devDependencies"]) {
    const declared = pkg[field] ?? {};
    const locked = root[field] ?? {};
    for (const [name, range] of Object.entries(declared)) {
      if (locked[name] !== range) {
        fail(
          "lockfile",
          `${field}.${name}: package.json wants "${range}", lockfile has ` +
            `"${locked[name] ?? "nothing"}" — run \`npm install\` and commit the lockfile`,
        );
      }
    }
  }
  if (lock.name !== pkg.name) {
    fail("lockfile", `lockfile name "${lock.name}" does not match package "${pkg.name}"`);
  }
}

// ── Report ───────────────────────────────────────────────────────────────────
if (failures.length === 0) {
  console.log(`ok   repo hygiene — ${files.length} tracked files, no issues`);
  process.exit(0);
}

const byCheck = new Map();
for (const { check, detail } of failures) {
  if (!byCheck.has(check)) byCheck.set(check, []);
  byCheck.get(check).push(detail);
}

console.error(`\nRepo hygiene failed — ${failures.length} issue(s):\n`);
for (const [check, details] of byCheck) {
  console.error(`  ${check}:`);
  for (const detail of details) console.error(`    • ${detail}`);
  console.error("");
}
console.error("Fix by removing the file from git (`git rm --cached <path>`) and");
console.error("adding it to .gitignore, or by correcting the offending line.\n");
process.exit(1);
